{"path":"/testbed/app/cache.py","content":""""Persistent shared JSON cache for public demonstration profiles.

The cache is a single JSON file on disk so that any process (including a brand
new one) can reuse values written by another.  Values remain valid while their
age is strictly less than ``CACHE_TTL`` seconds; after that the loader is
called again and the entry is replaced.  Entries have the shape
``{key: {"stored_at": epoch_seconds, "value": profile}}``.
"""
import json
import os
import tempfile
import time

from app.config import CACHE_PATH, CACHE_TTL


def _read_entries():
    """Load cache entries from disk, tolerating a missing or corrupt file."""
    try:
        with open(CACHE_PATH, "r", encoding="utf-8") as handle:
            entries = json.load(handle)
    except (OSError, ValueError):
        return {}
    return entries if isinstance(entries, dict) else {}


def _write_entries(entries):
    """Persist entries atomically so a new process always sees valid JSON."""
    directory = os.path.dirname(CACHE_PATH)
    if directory:
        os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(prefix=".profiles-", suffix=".tmp", dir=directory or ".")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(entries, handle)
        os.replace(tmp_path, CACHE_PATH)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def get_or_load(key, loader, now=None):
    """Return a fresh cached value, otherwise load, store, and return it."""
    now = time.time() if now is None else now
    entries = _read_entries()
    entry = entries.get(key)
    if isinstance(entry, dict):
        age = now - entry.get("stored_at", 0)
        if age < CACHE_TTL:
            return entry["value"]
    value = loader()
    entries[key] = {"stored_at": now, "value": value}
    _write_entries(entries)
    return value
"}

